SELECT CASE WHEN discount >= 0.3 THEN 'high' WHEN discount >= 0.07 THEN 'mid' ELSE 'low' END AS discount_bucket, ROUND(AVG(discount), 2) AS avg_discount, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, MAX(amount) - MIN(amount) AS amount_range FROM orders GROUP BY CASE WHEN discount >= 0.3 THEN 'high' WHEN discount >= 0.07 THEN 'mid' ELSE 'low' END HAVING MAX(discount) > 0.37;
